<?php
require_once __DIR__.'/../includes/marketplace.php';
$user=require_login('provider');
$stmt=db()->prepare('SELECT * FROM providers WHERE user_id=? LIMIT 1');$stmt->bind_param('i',$user['id']);$stmt->execute();$provider=$stmt->get_result()->fetch_assoc();if(!$provider)exit('Provider profile not found.');
if($provider['verification_status']==='pending'||$provider['verification_status']==='rejected'){$page_title='Provider Dashboard';require __DIR__.'/../includes/header.php';?><div class="container py-5"><div class="card p-4"><h1 class="h4">Provider account <?=e($provider['verification_status'])?></h1><p class="text-secondary mb-0"><?php if($provider['verification_status']==='pending'):?>Your business profile has been created. NamVoy verification is required before you can submit marketplace offers.<?php else:?>Your provider account is not currently eligible to receive or submit marketplace offers.<?php endif;?></p></div></div><?php require __DIR__.'/../includes/footer.php';exit;}
$profile=load_provider_matching_profile((int)$provider['id']);$responseHours=provider_average_response_hours((int)$provider['id']);$score=calculate_provider_namvoy_score($provider);
$stmt=db()->prepare("SELECT tr.*, (SELECT COUNT(*) FROM provider_bids pb WHERE pb.trip_request_id=tr.id AND pb.provider_id=?) AS already_bid FROM trip_requests tr WHERE tr.status IN ('published','receiving_offers') AND tr.expires_at > NOW() ORDER BY tr.created_at DESC");$stmt->bind_param('i',$provider['id']);$stmt->execute();$result=$stmt->get_result();$requests=[];while($r=$result->fetch_assoc())$requests[]=enrich_provider_match($r,$provider,$profile);usort($requests,static fn(array $a,array $b):int=>$b['match_score']<=>$a['match_score']);
$page_title='Provider Dashboard';require __DIR__.'/../includes/header.php';
?><div class="container py-5"><div class="d-flex justify-content-between align-items-center mb-4"><div><h1 class="h3 mb-1"><?=e($provider['business_name'])?></h1><p class="text-secondary mb-0">Verification: <?=e($provider['verification_status'])?> · Rating <?=number_format((float)$provider['rating'],1)?></p></div><div class="d-flex gap-2"><a class="btn btn-outline-dark" href="/provider/profile.php">Matching Profile</a><a class="btn btn-outline-dark" href="/provider/offers.php">My Offers</a><a class="btn btn-outline-dark" href="/provider/bookings.php">Bookings</a></div></div><div class="row g-3 mb-4"><div class="col-md-3"><div class="card p-3 stat-card"><div class="text-secondary">NamVoy Score</div><div class="h3 mb-0"><?=number_format($score,1)?><small class="fs-6">/100</small></div></div></div><div class="col-md-3"><div class="card p-3 stat-card"><div class="text-secondary">Response rate</div><div class="h3 mb-0"><?=number_format((float)$provider['response_rate'],0)?>%</div></div></div><div class="col-md-3"><div class="card p-3 stat-card"><div class="text-secondary">Avg response</div><div class="h3 mb-0"><?= $responseHours===null?'—':number_format($responseHours,1).'h' ?></div></div></div><div class="col-md-3"><div class="card p-3 stat-card"><div class="text-secondary">Cancellation</div><div class="h3 mb-0"><?=number_format((float)$provider['cancellation_rate'],0)?>%</div></div></div></div><div class="card"><div class="card-body"><div class="d-flex justify-content-between align-items-center"><div><h2 class="h5 mb-1">Matching travel requests</h2><p class="text-secondary small mb-0">Ranked using destination, budget, category and provider performance.</p></div><span class="badge text-bg-light"><?=count($requests)?> open RFQs</span></div><?php if(!$requests):?><p class="text-secondary mt-4 mb-0">No open requests right now.</p><?php else:?><div class="table-responsive mt-3"><table class="table align-middle"><thead><tr><th>Request</th><th>Match</th><th>Destination</th><th>Dates</th><th>Budget</th><th>Deadline</th><th></th></tr></thead><tbody><?php foreach($requests as $r):?><tr><td><a href="/provider/request-view.php?id=<?=$r['id']?>"><?=e($r['request_number'])?></a></td><td><span class="badge text-bg-dark"><?=number_format($r['match_score'],0)?>% <?=e($r['match_label'])?></span></td><td><?=e($r['destination'])?></td><td><?=e($r['start_date'])?> → <?=e($r['end_date'])?></td><td><?=e($r['currency'])?> <?=number_format((float)$r['budget_max'])?></td><td><?=e($r['expires_at']?:'—')?></td><td><?php if($r['already_bid']):?><span class="text-secondary">Bid submitted</span> · <a href="/provider/messages.php?request_id=<?=$r['id']?>">Message</a><?php else:?><a class="btn btn-sm btn-dark" href="/provider/bid-add.php?request_id=<?=$r['id']?>">Submit offer</a><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></div></div></div><?php require __DIR__.'/../includes/footer.php'; ?>